<script>
let learningQuestionIndex=<?php echo e($questions->count() ?: 1); ?>;
function learningQuestionMarkup(index){return `<section class="learning-card p-6" data-question><div class="mb-5 flex items-center justify-between"><h2 class="text-[22px] font-bold text-white light:text-[#003033]">BUAT_SIMULASI_SOAL</h2><button type="button" onclick="this.closest('[data-question]').remove();learningQuestionCount()" class="text-red-400">×</button></div><input type="hidden" name="questions[${index}][remove_image]" value="0" data-remove-image><label class="mb-2 block text-[10px] font-bold uppercase tracking-[0.14em] text-white light:text-black">Soal</label><div class="learning-question-row"><div class="learning-editor learning-question-editor"><div class="flex h-7 items-center gap-2 border-b border-[#3b494b] px-2 text-white light:text-black"><button type="button" onclick="learningWrap(this,'**','**')" class="h-5 w-5 text-[11px] font-bold">B</button><button type="button" onclick="learningWrap(this,'*','*')" class="h-5 w-5 text-[11px] italic">I</button><label class="learning-question-upload" title="Upload gambar soal"><input type="file" name="questions[${index}][image]" accept="image/jpeg,image/png,image/gif,image/webp" class="hidden" onchange="showLearningQuestionImage(this)"><svg class="h-3.5 w-3.5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M4 5h16v14H4V5Z"/><circle cx="9" cy="10" r="1.5"/><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="m5 17 4-4 3 3 2-2 5 3"/></svg></label><div class="learning-question-image" data-question-image></div></div><textarea required name="questions[${index}][question]" placeholder="Tulis soal disini..." class="w-full resize-y border-0 bg-transparent px-3 py-2 text-[14px] text-slate-100 outline-none light:text-[#1a2e28]"></textarea></div><div class="learning-qtype-dropdown"><input type="hidden" name="questions[${index}][question_type]" value="pilihan_ganda"><button type="button" onclick="toggleLearningTypeMenu(this)" class="learning-qtype-trigger"><span class="learning-qtype-icon">◉</span><svg class="h-2.5 w-2.5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="m7 10 5 5 5-5"/></svg></button><div class="learning-qtype-menu hidden"><button type="button" onclick="selectLearningType(this,'pilihan_ganda')">Pilihan Ganda</button><button type="button" onclick="selectLearningType(this,'uraian')">Uraian</button></div></div></div><div class="hidden"><select onchange="toggleLearningType(this)" data-type-proxy><option value="pilihan_ganda">PILIHAN GANDA</option><option value="uraian">URAIAN</option></select></div><div class="mt-5" data-mc><label class="mb-2 block text-[10px] font-bold uppercase tracking-[0.14em] text-white light:text-black">Jawaban</label><div class="space-y-2">${['a','b','c','d','e'].map((opt,i)=>`<label class="flex h-10 items-center gap-2 border border-[#3b494b] bg-[#0f1017] px-3 light:bg-[#ececec]"><input name="questions[${index}][option_${opt}]" placeholder="Option ${i+1}" class="min-w-0 flex-1 border-0 bg-transparent text-[12px] text-white outline-none light:text-[#1a2e28]"><input type="radio" name="questions[${index}][correct_option]" value="${opt}" ${i===0?'checked':''}></label>`).join('')}</div></div><div class="mt-5 hidden" data-essay><label class="mb-2 block text-[10px] font-bold uppercase tracking-[0.14em] text-white light:text-black">Flag / Kunci Jawaban</label><textarea name="questions[${index}][answer_key]" placeholder="Tulis kunci jawaban disini..." class="learning-editor w-full px-3 py-3 text-[13px] text-white outline-none light:text-[#1a2e28]"></textarea></div><div class="mt-5"><label class="mb-2 block text-[10px] font-bold uppercase tracking-[0.14em] text-white light:text-black">Keterangan Jawaban / Hint</label><textarea name="questions[${index}][hint]" placeholder="Tulis keterangan jawaban disini..." class="learning-editor w-full px-3 py-3 text-[13px] text-white outline-none light:text-[#1a2e28]"></textarea></div></section>`}
function addLearningQuestion(){document.getElementById('learning-questions').insertAdjacentHTML('beforeend',learningQuestionMarkup(learningQuestionIndex++));learningQuestionCount()}
function learningQuestionCount(){document.getElementById('learning-question-count').textContent=document.querySelectorAll('[data-question]').length}
function renderLearningAttachments(){const input=document.querySelector('input[name="attachments[]"]');const list=document.getElementById('learning-attachment-list');if(!input||!list)return;const icons=[...input.files].map(file=>file.type.startsWith('image/')?'<svg class="h-3.5 w-3.5 shrink-0 text-[#30A192]" fill="none" stroke="currentColor" viewBox="0 0 24 24"><rect x="3" y="5" width="18" height="14" rx="1.5" stroke-width="1.8"/><circle cx="9" cy="10" r="1.5" stroke-width="1.8"/><path stroke-linecap="round" stroke-linejoin="round" stroke-width="1.8" d="m5 17 4-4 3 3 2-2 5 3"/></svg>':file.type.startsWith('video/')?'<svg class="h-3.5 w-3.5 shrink-0 text-[#a855f7]" fill="none" stroke="currentColor" viewBox="0 0 24 24"><rect x="3" y="6" width="13" height="12" rx="1.5" stroke-width="1.8"/><path stroke-linecap="round" stroke-linejoin="round" stroke-width="1.8" d="m16 10 5-3v10l-5-3"/></svg>':'<svg class="h-3.5 w-3.5 shrink-0 text-gray-400" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="1.8" d="M7 3h7l4 4v14H7V3Z"/><path stroke-linecap="round" stroke-linejoin="round" stroke-width="1.8" d="M14 3v4h4"/></svg>');list.innerHTML=[...input.files].map((file,index)=>`<div class="flex items-center justify-between gap-2 border-b border-[#3b494b] px-2 py-1"><span class="flex min-w-0 items-center gap-2">${icons[index]}<span class="truncate">${file.name}</span></span><button type="button" class="text-red-400" onclick="removeLearningAttachment(${index})">×</button></div>`).join('')}
function showLearningFileName(input){const previous=window.learningAttachments||[];const transfer=new DataTransfer();[...previous,...input.files].forEach(file=>transfer.items.add(file));input.files=transfer.files;window.learningAttachments=[...input.files];renderLearningAttachments()}
function removeLearningAttachment(index){const input=document.querySelector('input[name="attachments[]"]');if(!input)return;const files=[...input.files].filter((_,i)=>i!==index);const transfer=new DataTransfer();files.forEach(file=>transfer.items.add(file));input.files=transfer.files;window.learningAttachments=files;renderLearningAttachments()}
function showLearningQuestionImage(input){const card=input.closest('[data-question]');const panel=card?.querySelector('[data-question-image]');const file=input.files?.[0];if(!panel)return;if(!file){panel.innerHTML='';panel.classList.remove('has-file');return}const flag=card.querySelector('[data-remove-image]');if(flag)flag.value='0';const name=file.name.length>16?file.name.slice(0,13)+'...':file.name;panel.innerHTML=`<span title="${file.name}">${name}</span><button type="button" onclick="removeLearningQuestionImage(this)">×</button>`;panel.classList.add('has-file')}
function removeLearningQuestionImage(button){const panel=button.closest('[data-question-image]');const card=panel?.closest('[data-question]');const input=card?.querySelector('input[type="file"][name*="[image]"]');if(input)input.value='';const flag=card?.querySelector('[data-remove-image]');if(flag)flag.value='1';if(panel){panel.innerHTML='';panel.classList.remove('has-file')}}
function learningWrap(button,open,close){const editor=button.closest('.learning-editor');const textarea=editor?.querySelector('textarea');if(!textarea)return;const start=textarea.selectionStart;const end=textarea.selectionEnd;const value=textarea.value;textarea.value=value.slice(0,start)+open+(value.slice(start,end)||'teks')+close+value.slice(end);textarea.focus();textarea.setSelectionRange(start+open.length,end+open.length)}
function toggleLearningType(select){const card=select.closest('[data-question]');card.querySelector('[data-mc]').classList.toggle('hidden',select.value==='uraian');card.querySelector('[data-essay]').classList.toggle('hidden',select.value!=='uraian')}
function toggleLearningTypeMenu(button){button.nextElementSibling.classList.toggle('hidden')}
function selectLearningType(button,type){const dropdown=button.closest('.learning-qtype-dropdown');const card=button.closest('[data-question]');dropdown.querySelector('input[type="hidden"]').value=type;dropdown.querySelector('.learning-qtype-icon').textContent=type==='pilihan_ganda'?'◉':'☰';dropdown.querySelector('.learning-qtype-menu').classList.add('hidden');const proxy=card.querySelector('[data-type-proxy]');proxy.value=type;toggleLearningType(proxy)}
document.addEventListener('click',event=>{if(!event.target.closest('.learning-qtype-dropdown'))document.querySelectorAll('.learning-qtype-menu').forEach(menu=>menu.classList.add('hidden'))})
document.querySelectorAll('input[name="level"]').forEach(input=>input.addEventListener('change',()=>{document.querySelectorAll('input[name="level"]').forEach(r=>r.closest('label').classList.remove('bg-green-300','bg-yellow-300','bg-red-300','text-[#061015]'));const active=input.closest('label');active.classList.add(input.value==='easy'?'bg-green-300':input.value==='medium'?'bg-yellow-300':'bg-red-300','text-[#061015]')}));document.querySelector('input[name="level"]:checked')?.dispatchEvent(new Event('change'));
document.querySelectorAll('[data-question]').forEach(card=>{const hidden=card.querySelector('.learning-qtype-dropdown input[type="hidden"]');const proxy=card.querySelector('[data-type-proxy]');if(hidden&&proxy)proxy.value=hidden.value;if(proxy)toggleLearningType(proxy)});
</script><?php /**PATH D:\laragon\www\ctf_project\resources\views/managemenlearning/partials/form.blade.php ENDPATH**/ ?>